input.code:
import unreal

# Inspect material graph expressions to understand the visual design
mel = unreal.MaterialEditingLibrary

for mat_name in ['M_CRT_Screen', 'M_CRT_Frame', 'M_CRT_Dot']:
    mat = unreal.load_asset(f"/Game/Materials/{mat_name}")
    if mat:
        print(f"=== {mat_name} ===")
        # Get all expressions in the material
        try:
            expressions = mat.get_editor_property('expressions')
            print(f"  Expression count: {len(expressions)}")
            for k, expr in enumerate(expressions):
                expr_class = expr.get_class().get_name()
                desc = ""
                try:
                    desc = expr.get_editor_property('desc')
                except:
                    pass
                # Try to get specific properties based on type
                extra = ""
                if 'Constant3' in expr_class or 'Constant4' in expr_class:
                    try:
                        c = expr.get_editor_property('constant')
                        extra = f" Color=({c.r:.3f}, {c.g:.3f}, {c.b:.3f})"
                    except:
                        pass
                elif 'Constant' in expr_class and 'Vector' not in expr_class:
                    try:
                        r = expr.get_editor_property('r')
                        extra = f" Value={r}"
                    except:
                        pass
                elif 'Texture' in expr_class:
                    try:
                        tex = expr.get_editor_property('texture')
                        extra = f" Tex={tex.get_name() if tex else 'None'}"
                    except:
                        pass
                print(f"    [{k}] {expr_class}{': ' + desc if desc else ''}{extra}")
        except Exception as e:
            print(f"  Error reading expressions: {e}")
        print()

