import unreal

# Check output log for Niagara errors
# Also try NiagaraFunctionLibrary to get system info
ns = unreal.load_asset("/Game/Niagara/NS_CRT_DotGrid")

# Try to get emitter data through the asset's exposed parameters
try:
    exposed_params = ns.get_editor_property('exposed_parameters')
    if exposed_params:
        print(f"Exposed parameters: {exposed_params}")
    else:
        print("No exposed parameters")
except:
    print("exposed_parameters not accessible")

# Try to check if system has compilation errors
try:
    # NiagaraSystem properties
    for prop in ['has_any_gpuemitters', 'requires_distance_field_data', 
                 'requires_depth_buffer', 'requires_early_view_data',
                 'requires_view_uniform_buffer', 'fixed_bounds',
                 'use_fixed_bounds']:
        try:
            val = ns.get_editor_property(prop)
            print(f"  {prop}: {val}")
        except:
            pass
except:
    pass

# Check via NiagaraFunctionLibrary
try:
    nfl_methods = [m for m in dir(unreal.NiagaraFunctionLibrary) if not m.startswith('_')]
    print(f"\nNiagaraFunctionLibrary methods: {nfl_methods}")
except:
    print("NiagaraFunctionLibrary not available")

