import unreal

ns_crt = unreal.load_asset('/Game/Niagara/NS_CRT_DotGrid')

# Enumerate emitters
emitters = ns_crt.get_editor_property('emitter_handles')
print(f"Emitter count: {len(emitters)}")
for i, eh in enumerate(emitters):
    name = eh.get_editor_property('name')
    inst = eh.get_editor_property('instance')
    print(f"\nEmitter[{i}]: {name}")
    if inst:
        print(f"  Type: {type(inst)}")
        try:
            sim_target = inst.get_editor_property('sim_target')
            print(f"  SimTarget (GPU/CPU): {sim_target}")
        except:
            print("  SimTarget: not accessible")

# Check exposed user parameters
try:
    params = ns_crt.get_editor_property('exposed_parameters')
    print(f"\n=== Exposed Parameters: {len(params)} ===")
    for p in params:
        print(f"  {p}")
except:
    pass

# Try system user parameters via script
try:
    user_params = ns_crt.get_editor_property('system_spawn_script')
    print(f"\nSystem spawn script: {user_params}")
except:
    pass

# Check parameter store / user variables
try:
    ep = ns_crt.get_editor_property('editor_parameters')
    print(f"\nEditor parameters: {ep}")
except:
    pass

